-- Replace cloned generic banks with dedicated screening papers for
-- MIG Welder, TIG Welder, Mason (bricks/plaster) and Dubai Cleaner (Male/Female).
-- Option order is shuffled at test time in loadQuizItems / loadQuizItemsFromJson.

SELECT v.skill_code, NULL, 10, 'random_active', '{}'::uuid[], 60, true
FROM (VALUES
  ('MIG Welder'),
  ('TIG Welder'),
  ('Mason (bricks/plaster)'),
  ('Cleaner (Male)'),
  ('Cleaner (Female)')
) AS v(skill_code)
WHERE NOT EXISTS (
  SELECT 1
  FROM public.skill_quiz_configs c
  WHERE c.skill_code = v.skill_code
    AND c.region IS NULL
);

UPDATE public.skill_quiz_configs
SET questions_to_show = 10,
    pass_score = 60,
    selection_mode = 'random_active',
    selected_ids = '{}'::uuid[],
    active = true,
    updated_at = now()
WHERE region IS NULL
  AND skill_code IN (
    'MIG Welder',
    'TIG Welder',
    'Mason (bricks/plaster)',
    'Cleaner (Male)',
    'Cleaner (Female)'
  );

DELETE FROM public.worker_skill_quiz_responses
WHERE quiz_item_id IN (
  SELECT id
  FROM public.worker_skill_quiz_items
  WHERE skill_code IN (
    'MIG Welder',
    'TIG Welder',
    'Mason (bricks/plaster)',
    'Cleaner (Male)',
    'Cleaner (Female)'
  )
);

DELETE FROM public.worker_skill_quiz_items
WHERE skill_code IN (
  'MIG Welder',
  'TIG Welder',
  'Mason (bricks/plaster)',
  'Cleaner (Male)',
  'Cleaner (Female)'
);

